namespace Fanex.Tarus.BetList.DataAccess.SportingSolutions
{
    using System.Collections.Generic;
    using System.Data;
    using System.Diagnostics.CodeAnalysis;
    using DNAide.Core;
    using Fanex.Data;
    using Fanex.Tarus.BetList.Criteria.SportingSolutions;

    [SuppressMessage("Microsoft.StyleCop.CSharp.DocumentationRules", "SA1600:ElementsMustBeDocumented")]
    public class SportingSolutionsDataAccess : ISportingSolutionsDataAccess
    {
        public List<dynamic> GetSportingSolutionsResult(GetSportingSolutionsResultCriteria criteria)
        {
            var dataTable = new DataTable();
            using (ObjectDb objDb = new ObjectDb(criteria.GetSettingKey()))
            {
                objDb.AddInParameter("matchid", DbType.Int32, criteria.Matchid);
                objDb.AddInParameter("resourceid", DbType.String, criteria.Resourceid);
                var ds = objDb.ExecuteDataSet();
                if (ds != null && ds.Tables.Count > 0)
                {
                    dataTable = ds.Tables[0];
                }
            }

            var result = new List<dynamic>();
            if (dataTable != null && dataTable.Rows.Count > 0)
            {
                foreach (DataRow row in dataTable.Rows)
                {
                    result.Add(new
                    {
                        resultvalue = CastAide.AsString(row["resultvalue"])
                    });
                }
            }

            return result;
        }
    }
}
